const b = $json.body || {};
const required = ['order_number','name','phone','amount','payment_method','address','pincode'];
const missing = required.filter(k => b[k] === undefined || b[k] === '');
if (missing.length) throw new Error('Missing fields: ' + missing.join(', '));

const phone = String(b.phone).replace(/\D/g, '').slice(-10);
if (phone.length !== 10) throw new Error('Invalid phone number');

return { json: {
  order_number: String(b.order_number),
  name: String(b.name).trim(),
  phone,
  email: b.email || null,
  amount: Number(b.amount),
  payment_method: String(b.payment_method).toLowerCase() === 'cod' ? 'cod' : 'prepaid',
  address: String(b.address).trim(),
  pincode: String(b.pincode).trim(),
  items: b.items || []
}};

