const r = $('Save order').item.json;

// Read the AI's answer safely; if anything fails, fall back to rules only
let ai = { suspicious: false, reason: 'AI check unavailable' };
try {
  const text = $json.choices?.[0]?.message?.content ?? '';
  const match = text.match(/\{[\s\S]*\}/);
  if (match) ai = JSON.parse(match[0]);
} catch (e) {}

let score = r.rule_score;
const reasons = [...r.rule_reasons];
if (ai.suspicious) { score += 30; reasons.push('AI: ' + ai.reason); }
score = Math.min(score, 100);

const isCod = r.order.payment_method === 'cod';
const status = (isCod && score >= 50) ? 'pending_confirmation' : 'confirmed';

return { json: {
  id: r.order.id,
  order_number: r.order.order_number,
  status,
  risk_score: score,
  risk_reasons: reasons
}};
